//! NSPasteboard adapter. A handle is created per call, so this type is `Send`.
use super::{Content, Pasteboard};
use objc2::{rc::Retained, runtime::ProtocolObject};
use objc2_app_kit::{
    NSPasteboard, NSPasteboardTypeFileURL, NSPasteboardTypeString, NSPasteboardWriting,
};
use objc2_foundation::{NSArray, NSString, NSURL};
use std::{io, path::PathBuf};

/// Password managers and similar apps mark secrets with these (nspasteboard.org).
const SECRET_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

#[derive(Default)]
pub struct MacPasteboard;

fn general() -> Retained<NSPasteboard> {
    NSPasteboard::generalPasteboard()
}

impl Pasteboard for MacPasteboard {
    fn change_count(&self) -> i64 {
        general().changeCount() as i64
    }
    fn read(&self) -> Option<Content> {
        let board = general();
        let types = board.types()?;
        if types
            .iter()
            .any(|t| SECRET_TYPES.contains(&t.to_string().as_str()))
        {
            return None;
        }
        // Finder puts file URLs on the board; they take precedence over the file names as text.
        if let Some(items) = board.pasteboardItems() {
            let files: Vec<PathBuf> = items
                .iter()
                .filter_map(|item| {
                    let url = item.stringForType(unsafe { NSPasteboardTypeFileURL })?;
                    let url = NSURL::URLWithString(&url)?;
                    url.path().map(|p| PathBuf::from(p.to_string()))
                })
                .collect();
            if !files.is_empty() {
                return Some(Content::Files(files));
            }
        }
        let text = board.stringForType(unsafe { NSPasteboardTypeString })?;
        let text = text.to_string();
        (!text.is_empty()).then_some(Content::Text(text))
    }
    fn write_text(&mut self, text: &str) -> io::Result<()> {
        let board = general();
        board.clearContents();
        if board.setString_forType(&NSString::from_str(text), unsafe { NSPasteboardTypeString }) {
            Ok(())
        } else {
            Err(io::Error::other("pasteboard refused text"))
        }
    }
    fn write_files(&mut self, paths: &[PathBuf]) -> io::Result<()> {
        let urls: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = paths
            .iter()
            .filter_map(|p| p.to_str())
            .map(|p| ProtocolObject::from_retained(NSURL::fileURLWithPath(&NSString::from_str(p))))
            .collect();
        if urls.len() != paths.len() {
            return Err(io::Error::other("non-UTF-8 path"));
        }
        let board = general();
        board.clearContents();
        if board.writeObjects(&NSArray::from_retained_slice(&urls)) {
            Ok(())
        } else {
            Err(io::Error::other("pasteboard refused files"))
        }
    }
}
